'use client';
import React from 'react';

import EmojiPicker from 'emoji-picker-react';

// Reactions as a rating scale: a terminal bar (no "+") stretched to the
// card width. onReactionClick receives the chosen point on the scale.
export type PickerExampleProps = {
  /** The picker root: EmojiPicker, or a styled() wrapper of it. */
  Root?: React.ComponentType<Omit<React.ComponentProps<typeof EmojiPicker>, 'theme'>>;
  className?: string;
};

export function PickerExample({
  Root: RootComponent = EmojiPicker,
  className,
}: PickerExampleProps) {
  return (
    <RootComponent
      className={className}
      reactionsDefaultOpen
      allowExpandReactions={false}
      reactions={['1f620', '1f641', '1f610', '1f603', '1f929']}
      onReactionClick={() => undefined}
    />
  );
}

/* Intercom — conversation rating in a support messenger: brand gradient
   header and a five-point emoji scale as a terminal reactions bar. */
/* Picker styles — the source of truth for every stack variant. */
.intercom-scale {
  --epr-reactions-bg-color: #f4f6fb;
  --epr-picker-border-color: transparent;
  --epr-hover-bg-color: #e4e9f7;
  --epr-hover-bg-color-reduced-opacity: #e4e9f7;
  --epr-emoji-size: 32px;
  margin: 0 auto;
}
.intercom-scale[data-epr-part='root'] {
  width: 100%;
  height: 60px;
  border-radius: 14px;
  backdrop-filter: none;
}
.intercom-scale [data-epr-part='reactions'] {
  justify-content: space-around;
  width: 100%;
}
.intercom-scale [data-epr-part='reaction'] {
  border-radius: 12px;
}

/* Generated by scripts/generateRecipes.mts from picker.css — do not edit. */
